using Test.TestLexer;

namespace Test.TestSourceReader;

/// <summary>
/// SPITBOL generates an expression from the top, its operands left to right, and checks that a name is a name before it generates what
/// is inside it, so of the errors its code generation finds the first in that order is the statement's: A . (1 / 0), .(1 / 0) and
/// .(-'a') are 212, not 14 or 10, where (1 / 0) . A, .F(1 / 0) and .X&lt;1 / 0&gt; are 14 (the left operand comes first; a call or an
/// element is a name whose arguments are generated by value), F(.('a' + 1), 1 / 0) is 212 and F(1 / 0, .('a' + 1)) 14. dotnet found
/// the errors bottom up and reported the first fold error it met. Found by the infinite_snobol4 generator (.(+g(6) | BREAKX('xh4r') +
/// 2.5), seed 633881: sbl 212, dotnet 1). Every expected number is what sbl -b listed for the same statement.
/// </summary>
[TestClass]
public class NameBeforeFold
{
    [TestMethod]
    public void TEST_NameBeforeFold_the_first_error_in_spitbols_order_is_the_statements()
    {
        var build = SetupTests.SetupScript("-b -n", @"        Y = .(1 / 0)
        Y = .(-'a')
        Y = A . (1 / 0)
        Y = (1 / 0) . A
        Y = .F(1 / 0)
        Y = .X<1 / 0>
        Y = 1     :(1 / 0)
        (1 / 0) = 5
        Y = (1 / 0) . (2 / 0)
        Y = ~(1 / 0)
        Y = .(1 / 0) + (2 / 0)
        Y = (2 / 0) + .(1 / 0)
        Y = @(1 / 0)
        Y = &(1 / 0)
        Y = $(1 / 0)
        Y = A $ (1 / 0)
        Y = .(1 / 0 | 'a')
        Y = .((1 / 0) 'a')
        Y = .(LEN(-1))
        Y = A . LEN(-1)
        Y = .(X ? (1 / 0))
        Y = .((1 / 0) ? X)
        Y = .(1 / 0, 2)
        Y = A . ('a' + 1)
        Y = 'a' + 1 . A
        Y = .*(1 / 0)
        Y = .(-FAIL)
        Y = 'a' .(+X | BREAKX('xh') + 2.5) 'b'
        Y = .(+X | BREAKX('xh') + 2.5)
        Y = (1 / 0) $ ('a' + 1)
        Y = .X<1 / 0, 'a' + 1>
        Y = F(1 / 0, .('a' + 1))
        Y = F(.('a' + 1), 1 / 0)
        Y = (.('a' + 1), 1 / 0)
        Y = (1 / 0, .('a' + 1))
        Y = *(1 / 0) . ('a' + 1)
        X ('a' + 1) = 1 / 0
        (X = 1 / 0) . ('a' + 1)
        Y = X . ('a' + 1) :(1 / 0)
        Y = 1 :S(1 / 0) F(.('a' + 1))
END");
        CollectionAssert.AreEqual(new[] { 212, 212, 212, 14, 14, 14, 212, 212, 14, 14, 212, 14, 212, 212, 14, 212, 212, 212, 121, 121, 212, 212, 212, 212, 2, 14, 212,
                212, 212, 14, 14, 14, 212, 212, 14, 14, 1, 14, 212, 212 },
            build.ErrorCodeHistory.ToArray());
    }
}
